/*
 PrimeVideoDB - PostgreSQL 14+
 Versión robusta para uso académico.
 IMPORTANTE: ejecutar conectado a una base llamada primevideodb.
 - Carga transaccional.
 - person.name usa TEXT.
 - content_person deduplicada por (content_id, person_id, role).
 - Validaciones finales de conteo e integridad.
*/

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

BEGIN;

DROP VIEW IF EXISTS vw_content_summary;
DROP TABLE IF EXISTS content_country CASCADE;
DROP TABLE IF EXISTS content_genre CASCADE;
DROP TABLE IF EXISTS content_person CASCADE;
DROP TABLE IF EXISTS country CASCADE;
DROP TABLE IF EXISTS genre CASCADE;
DROP TABLE IF EXISTS person CASCADE;
DROP TABLE IF EXISTS content CASCADE;

CREATE TABLE content (
    id INTEGER PRIMARY KEY,
    source_id VARCHAR(20) NOT NULL UNIQUE,
    content_type VARCHAR(20) NOT NULL
        CHECK (content_type IN ('MOVIE','TV_SHOW','OTHER')),
    title VARCHAR(500) NOT NULL,
    date_added DATE NULL,
    release_year SMALLINT NULL,
    rating VARCHAR(30) NULL,
    duration_value INTEGER NULL,
    duration_unit VARCHAR(20) NULL
        CHECK (duration_unit IS NULL OR duration_unit IN ('MINUTES','SEASONS','OTHER')),
    duration_text VARCHAR(50) NULL,
    description TEXT NULL
);

CREATE TABLE person (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL
);

CREATE TABLE genre (
    id INTEGER PRIMARY KEY,
    name VARCHAR(150) NOT NULL UNIQUE
);

CREATE TABLE country (
    id INTEGER PRIMARY KEY,
    name VARCHAR(150) NOT NULL UNIQUE
);

CREATE TABLE content_person (
    content_id INTEGER NOT NULL,
    person_id INTEGER NOT NULL,
    role VARCHAR(20) NOT NULL CHECK (role IN ('DIRECTOR','CAST')),
    credit_order INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (content_id, person_id, role),
    CONSTRAINT fk_cp_content FOREIGN KEY (content_id)
        REFERENCES content(id) ON DELETE CASCADE,
    CONSTRAINT fk_cp_person FOREIGN KEY (person_id)
        REFERENCES person(id) ON DELETE CASCADE
);

CREATE TABLE content_genre (
    content_id INTEGER NOT NULL,
    genre_id INTEGER NOT NULL,
    PRIMARY KEY (content_id, genre_id),
    CONSTRAINT fk_cg_content FOREIGN KEY (content_id)
        REFERENCES content(id) ON DELETE CASCADE,
    CONSTRAINT fk_cg_genre FOREIGN KEY (genre_id)
        REFERENCES genre(id) ON DELETE CASCADE
);

CREATE TABLE content_country (
    content_id INTEGER NOT NULL,
    country_id INTEGER NOT NULL,
    PRIMARY KEY (content_id, country_id),
    CONSTRAINT fk_cc_content FOREIGN KEY (content_id)
        REFERENCES content(id) ON DELETE CASCADE,
    CONSTRAINT fk_cc_country FOREIGN KEY (country_id)
        REFERENCES country(id) ON DELETE CASCADE
);

CREATE INDEX idx_content_title ON content(title);
CREATE INDEX idx_content_year ON content(release_year);
CREATE INDEX idx_content_type ON content(content_type);
CREATE INDEX idx_cp_person ON content_person(person_id);
CREATE INDEX idx_cg_genre ON content_genre(genre_id);
CREATE INDEX idx_cc_country ON content_country(country_id);



Copyright: TV TOKYO'),
(701, 's701', 'MOVIE', 'The Curse of Robert', NULL, 2016, '16+', 80, 'MINUTES', '80 min', 'Emily Barker is a cash strapped student trying to make money as a cleaner, working nights at the East Falls Museum. But her peaceful graveyard shift turns into a time of terror when she discovers that one of the exhibits, a creepy vintage doll named Robert, is alive and wreaking havoc after hours.'),
(702, 's702', 'MOVIE', 'The Curse Of Hobbes House', NULL, 2020, NULL, 83, 'MINUTES', '83 min', 'When down on her luck Jane Dormant learns about the death of her Aunt Alexandra she expects a life-saving inheritance but finds herself battling bloodthirsty Zombies instead, fighting for her life.'),
(703, 's703', 'MOVIE', 'The Curse of Buckout Road', NULL, 2019, '18+', 96, 'MINUTES', '96 min', 'A college class project on creation and destruction of modern myth, turns terrifying when a trio of young people come to realize the urban legends surrounding the famed Buckout Road may, in fact, be REAL.'),
(704, 's704', 'MOVIE', 'The Creepy Line', NULL, 2018, '7+', 81, 'MINUTES', '81 min', 'The Creepy Line reveals the stunning degree to which society is manipulated by Google and Facebook and blows the lid off the remarkably subtle - hence powerful - manner in which they do it. Offering first-hand accounts, scientific experiments and detailed analysis, the film examines what is at risk when these tech titans have free reign to utilize the public''s most private and personal data.'),
(705, 's705', 'MOVIE', 'The Creeping Flesh', NULL, 1973, 'PG', 92, 'MINUTES', '92 min', 'A Victorian-age scientist returns to London with his paleontological bag-of-bones discovery from Papua New Guinea. Unfortunately, when exposed to water, flesh returns to the bones unleashing a malevolent being on the scientist''s family and friends.'),
(706, 's706', 'MOVIE', 'The Cowboy And The Senorita', NULL, 1944, '13+', 54, 'MINUTES', '54 min', 'A shady gambler attempts to snatch the rights to a teenage girl''s inherited gold mining claim, until a cowboy and his friend save the day.'),
(707, 's707', 'MOVIE', 'The Cowboy and The Lady', NULL, 1936, '7+', 92, 'MINUTES', '92 min', 'A lonely socialite masquerades as a maid and meets an unpretentious, plain-spoken cowboy who is unaware of her true identity.'),
(708, 's708', 'MOVIE', 'The Coverup', NULL, 2009, 'R', 95, 'MINUTES', '95 min', 'Based on a True Story - surrounding the 1984 death of an Iowa teenager (Michael Welch) after his arrest by the Marshalltown Police Department. A young lawyer (Gabriel Mann) is hired to fight a corrupt Police Department and bring healing to a fractured family in this small town legal drama.'),
(709, 's709', 'MOVIE', 'The Court Jester', NULL, 1956, 'ALL', 101, 'MINUTES', '101 min', 'Danny Kaye plays kind-hearted entertainer Hawkins who disguises himself as the legendary king of jesters, Giacomo. Hawkins infiltrates the court of the evil villain Basil Rathbone, but when a sorceress hypnotises him, royal chaos ensues.'),
(710, 's710', 'MOVIE', 'The Courageous Dr. Christian', NULL, 1940, 'ALL', 66, 'MINUTES', '66 min', 'In this second movie in the Dr. Christian series, kindly Dr. Christian tends to the needs of the inhabitants living in the squalor of the town''s shanty district. The indigents and Dr. Christian are largely ignored by the local townspeople, until an epidemic of spinal meningitis threatens the entire community.'),
(711, 's711', 'MOVIE', 'The Count of Monte Cristo', NULL, 1975, '13+', 103, 'MINUTES', '103 min', 'A classic tale of injustice, revenge and retribution, in which Edmond Dantes is falsely accused by three men of conspiring with Napoleon. Richard Chamberlain stars in this definitive adaptation of Alexandre Dumas'' perennial favourite novel.'),
(712, 's712', 'MOVIE', 'The Cotton Pickin Truth Still On The Plantation', NULL, 2020, '18+', 94, 'MINUTES', '94 min', 'The Cotton Pickin'' Truth... Still On The Plantation is a documentary film that calls for the re-writing of American history as we know it. The film uncovers modern-day slavery in the Mississippi Delta in 2009. As a result of the film''s exposure to many dedicated Mississippians, the state of Mississippi ratified the 13th amendment in totality in February of 2013.'),
(713, 's713', 'MOVIE', 'The Corrupted', NULL, 2020, 'R', 104, 'MINUTES', '104 min', 'Liam McDonagh (Sam Claflin), an ex-con attempting to live a peaceful life is thrust into action when his brother becomes entangled in a dangerous web of corruption. Liam must risk it all to save his family.'),
(714, 's714', 'MOVIE', 'The Confessor', NULL, 2005, 'PG-13', 91, 'MINUTES', '91 min', 'A worldly and urbane priest is forced to challenge his comfortable existence as an ecclesiastical spin-doctor when he comes to believe in the innocence of a young priest accused of murder. His only ally, a journalist, is also his former sweetheart...'),
(715, 's715', 'MOVIE', 'The Competition', NULL, 1980, 'PG', 126, 'MINUTES', '126 min', 'While competing against each other in a music contest, two pianists (Richard Dreyfuss, Amy Irving) fall in love and must battle to stay together in case either of them wins. Oscar-nominated for Best Song and Best Film Editing.'),
(716, 's716', 'MOVIE', 'The Collector', NULL, 2009, 'R', 90, 'MINUTES', '90 min', 'Desperate to repay his debt to his ex-wife, an ex-con plots a heist at his new employer''s country home, unaware that a second criminal has also targeted the property, and rigged it with a series of deadly traps.'),
(717, 's717', 'MOVIE', 'The Cleansing', NULL, 2019, '18+', 98, 'MINUTES', '98 min', 'A young girl in medieval Britain must watch her mother undergo torture and murder for practicing witchcraft by The Cleanser.'),
(718, 's718', 'MOVIE', 'The Christmas Lodge', NULL, 2014, 'G', 89, 'MINUTES', '89 min', 'During a weekend trip to the mountains, Mary finds herself at the now run-down lodge where she spent the holidays with her family growing up. She becomes determined to restore the building to its former glory. Inspired by her grandfather and guided by her grandmother in heaven, Mary throws herself into the project.'),
(719, 's719', 'MOVIE', 'The Christmas Elves', NULL, 2016, 'ALL', 52, 'MINUTES', '52 min', 'Catch this whimsical holiday film bursting with comical elfin escapades! Based on the classic tale of the Shoemaker and the Elves, Hans the shoemaker is helped by a group of mismatched elves who want to work for Santa Claus. Produced by Golden Films.'),
(720, 's720', 'MOVIE', 'The Christmas Candle', NULL, 2013, 'PG', 100, 'MINUTES', '100 min', 'Legend has it every 25 years an angel touches a single candle, and whomever lights this candle receives a miracle on Christmas Eve. But in 1890, at the dawn of the electric age, this centuries old legend may come to an end when a progressive young minister arrives. Now, the fiery candlemaker must fight to preserve the legacy of the Christmas Candle. From bestselling author, Max Lucado.'),
(721, 's721', 'MOVIE', 'The Changeling', NULL, 1993, NULL, 90, 'MINUTES', '90 min', 'Bob Hoskins stars in an adaptation of Thomas Middleton and William Rowley''s classic Jacobean tragedy. A tale of lust and revenge between two ambiguous, guilt-ridden individuals.'),
(722, 's722', 'TV_SHOW', 'The Challenge: ETA', NULL, 2020, '16+', 1, 'SEASONS', '1 Season', 'The Challenge ETA is an eight-episode documentary series about the Guardia Civil''s fight against the Basque terrorist band ETA. A fight that lasted for half a century, until the dissolution of the band and its definitive renunciation of weapons. The Challenge ETA is an ambitious production that aims to mark a milestone in this important episode of the recent history of Spain.'),
(723, 's723', 'TV_SHOW', 'The Carol Burnett Show', NULL, 1972, '13+', 1, 'SEASONS', '1 Season', 'For over a decade, this extravaganza of comedy, song and dance defined entertainment for TV viewers. The Carol Burnett Show brought the actors and audience close together. Beloved for her signature audience Questions and Answers famous Tarzan yell, Burnett''s brilliant troupe stars Harvey Korman, Vicki Lawrence and Lyle Waggoner.'),
(724, 's724', 'MOVIE', 'The Capture', NULL, 1950, '18+', 102, 'MINUTES', '102 min', 'Lin Vanner (Ayres) captures and turns in a fellow oil company employee whom he believes was behind a payroll robbery. The accused man dies in police custody, and Lin feels overwhelmingly responsible for the man''s death, wondering if he was actually innocent of the crime. His guilt causes Lin to lose his job and his fiancee, and to soothe his conscience, Lin seeks out the dead man''s widow, Evelyn (Wright). The two fall in love and marry without Evelyn ever knowing about Lin''s past and feelings of guilt. When Lin discovers who really commited the robbery, he goes after the man, who dies accidentally in the ensuing chase. Lin is now accused of murdering the man, and must become a fugitive on the run. This is the lost masterpiece of director John Sturges.'),
(725, 's725', 'MOVIE', 'The Bumble Nums - Season 4', NULL, 2020, 'ALL', 43, 'MINUTES', '43 min', 'Humble, Stumble and Grumble are back! This time their adventures are taking them to lots of exciting places. There''s riding a shopping cart in Upsidedown Town, swinging on vines in an enchanted forest, surfing in the ocean and trying to capture a colossal cauliflower from an uncharted island!'),
(726, 's726', 'MOVIE', 'The Bridgewater Triangle', NULL, 2013, '13+', 91, 'MINUTES', '91 min', '"The Bridgewater Triangle" hosts an unusually high volume of reports involving strange happenings, baffling mysteries and sinister deeds. From ghostly hauntings and cryptid animal sightings, to UFO encounters and evidence of satanic ritual sacrifice, this 200-square mile region in Southeastern Massachusetts serves as one of the world''s most diverse and well-known hotspots for paranormal activity'),
(727, 's727', 'MOVIE', 'The Bridges at Toko-Ri', NULL, 1955, '13+', 103, 'MINUTES', '103 min', 'Set during the Korean War, a Navy fighter pilot must come to terms with his own ambivalence towards the war and the fear of having to bomb a set of highly defended bridges. The ending of this grim war is all tension.'),
(728, 's728', 'MOVIE', 'The Bray Road Beast', NULL, 2020, '13+', 67, 'MINUTES', '67 min', 'In the early 1990''s a rural Wisconsin community called Elkhorn was at the center of a series of real-life werewolf sightings. As local reporter, Linda Godfrey, began her investigations into the "Beast of Bray Road".'),
(729, 's729', 'MOVIE', 'THE BRANCH', NULL, 2019, 'ALL', 89, 'MINUTES', '89 min', 'The employees of the Industrial Zone Branch of the Banco Nacional Obrero, after a long vacation, must return to work and resume their routine, something that will not be easy, because their bosses came up with the idea of conducting a survey of work environment, which will reveal true personalities in the office.'),
(730, 's730', 'MOVIE', 'The Boys of St. Vincent', NULL, 1992, '16+', 93, 'MINUTES', '93 min', 'This realistic dramatization follows the desperate struggle by young residents of a Roman Catholic orphanage to escape their nightmare of physical and sexual abuse. Their cries for help go unheeded, although a concerned janitor and a no-nonsense cop wage a personal crusade to uncover the terrible truth, and end the suffering.'),
(731, 's731', 'TV_SHOW', 'The Boys', NULL, 2020, '18+', 2, 'SEASONS', '2 Seasons', 'All Episodes Available. In a more intense Season 2 of THE BOYS, Butcher, Hughie and the team reel from their losses in Season 1. On the run from the law, they struggle to fight back against the Superheroes. Meanwhile Vought, the hero management company, cashes in on the panic over Supervillains, and a new hero, Stormfront, shakes up the company and challenges an already unstable Homelander.'),
(732, 's732', 'TV_SHOW', 'The Bold and the Beautiful', NULL, 2015, '13+', 1, 'SEASONS', '1 Season', 'The Bold and the Beautiful is a three-time Emmy Award-winning drama set in Los Angeles that tells the story of high fashion glamour, honor, romance, passion and most importantly, family.'),
(733, 's733', 'TV_SHOW', 'The Boat Show', NULL, 2018, '13+', 1, 'SEASONS', '1 Season', 'The Boat Show is a program dedicated to nautical lovers and boat owners. It is the only show in the world completely dedicated to the nautical world, made with passion by a team of experts with more than 15 years of experience.'),
(734, 's734', 'TV_SHOW', 'The Block', NULL, 2018, '13+', 7, 'SEASONS', '7 Seasons', 'The Block introduces four couples who are taking on one of the potentially most rewarding challenges they will ever face.'),
(735, 's735', 'MOVIE', 'The Black Velvet Gown', NULL, 1993, NULL, 103, 'MINUTES', '103 min', 'In 1830s England, a mother and daughter fight for a better life and challenge the prejudice of their society in this International Emmy® Award winner for Best Drama.'),
(736, 's736', 'MOVIE', 'The Black Kungfu Experience', NULL, 2013, NULL, 56, 'MINUTES', '56 min', 'This film focuses on how a group of African American pioneers became respected masters in a subculture dominated by Chinese and white men.'),
(737, 's737', 'MOVIE', 'The Black Candle', NULL, 1991, '16+', 103, 'MINUTES', '103 min', 'Joe Skinner marries Lily Whitmore, to give a name to her illegitimate child by Lionel, the opportunistic son of an impoverished aristocrat. Lionel, however, has his sights set on Victoria, the cousin of hard-working Bridget Mordaunt. When Joe''s brother Fred threatens his marriage plans, Lionel murders him and the blame falls on Joe.'),
(738, 's738', 'MOVIE', 'The Bishop''s Wife', NULL, 1948, '13+', 110, 'MINUTES', '110 min', 'An angel in human form enters the life of a bishop in order to help him build a new cathedral and repair his fractured marriage.'),
(739, 's739', 'MOVIE', 'The Bigamist', NULL, 1953, '13+', 79, 'MINUTES', '79 min', 'Harry and Eve Graham are trying to adopt a baby. The head of the agency senses Harry has a secret and does some investigating. He soon discovers Harry has done an unusual amount of traveling from his home in San Francisco to LA.'),
(740, 's740', 'MOVIE', 'The Big Sleep', NULL, 2007, 'NR', 29, 'MINUTES', '29 min', 'The Big Sleep play the Insound party - complete with beach balls, cheap beer, and good instrumental music.'),
(741, 's741', 'MOVIE', 'The Big Cat', NULL, 1949, '18+', 77, 'MINUTES', '77 min', 'The story of the struggle for survival of a few inhabitants in the "high country" of Utah in 1933, during the worst draught they have ever known in the Great Depression. City boy Danny arrives at his Uncle Gil''s ranch to help the family out. Although lacking in ranch hand skills, the boy manages to save his uncle''s life when a "Big Cat" (a cougar) comes onto the ranch, desperate for the water it needs to survive. A local backwoodsman spends the film trying to track and kill the cougar before it kills a human, and a romance blooms between two young locals. A beautifully filmed outdoor drama.'),
(742, 's742', 'MOVIE', 'The Big Black Comedy Show, Vol. 5', NULL, 2006, NULL, 88, 'MINUTES', '88 min', 'An outrageously funny stand-up comedy special with an all-star line-up of African American entertainers, hosted by the multi-talented Michael Colyar.'),
(743, 's743', 'TV_SHOW', 'The Beverly Hillbillies', NULL, 1963, 'TV-PG', 1, 'SEASONS', '1 Season', 'The Clampett family are simple folk, happily living off the land in the Ozarks. They want for nothing and ask for nothing. When Jed Clampett accidentally discovers oil on his family''s property, they strike it rich, becoming millionaires. With their newfound wealth, the Clampetts decide to enter a new life... in Beverly Hills, California.'),
(744, 's744', 'TV_SHOW', 'The Best of The Three Stooges in Color!', NULL, 1936, '7+', 1, 'SEASONS', '1 Season', 'The Stooges are back in these hilarious episodes, where you''ll see Larry, Curly, Moe and Shemp perform the comedy that made them famous. Remastered from the original 35mm film elements, these classic Three Stooges shorts are brought to you fully restored and in color, looking better than they ever have before!'),
(745, 's745', 'TV_SHOW', 'The Best of Mister Rogers'' Neighborhood', NULL, 1975, 'TV-Y', 1, 'SEASONS', '1 Season', 'MISTER ROGERS'' NEIGHBORHOOD is more than a television program - it''s a visit with a trusted friend and guide, exploring with children things that matter in their everyday world - feelings, questions and concerns.'),
(746, 's746', 'TV_SHOW', 'The Bernie Mac Show', NULL, 2006, 'TV-PG', 5, 'SEASONS', '5 Seasons', 'A stand up comedian suddenly becomes a father when he takes custody of his sister''s three children.'),
(747, 's747', 'MOVIE', 'The Benefactor', NULL, 2016, '16+', 93, 'MINUTES', '93 min', 'A newly married couple are forced to navigate the all-consuming interest of a powerful, mysterious, and possessive philanthropist.'),
(748, 's748', 'MOVIE', 'The Beckoning Silence', NULL, 2007, '13+', 73, 'MINUTES', '73 min', 'The climber Joe Simpson was 25 when he had an accident that nearly killed him. He wrote a book - Touching the Void - about his extraordinary battle to survive. Now he is going back to the mountain that first him inspired to climb. To tell a story that has haunted him since he was a boy.'),
(749, 's749', 'MOVIE', 'The Beautician And The Beast', NULL, 1997, 'PG', 107, 'MINUTES', '107 min', 'A New York cosmetologist mistakenly thought to be a science teacher is offered a job to teach the children of an Eastern European dictator.'),
(750, 's750', 'MOVIE', 'The Beastmaster', NULL, 1982, '13+', 118, 'MINUTES', '118 min', 'Marc Singer and Tanya Roberts in a sword-and-sorcery fantasy about a young man''s search for revenge. Armed with supernatural powers, the handsome hero and his animal allies wage war against marauding forces.');

